const htmlElement=document.documentElement,withThemeToggle=document.getElementById("withThemeToggle");console.log(withThemeToggle),withThemeToggle.addEventListener("click",(()=>{console.log(withThemeToggle),htmlElement.classList.toggle("with"),localStorage.setItem("theme",htmlElement.classList.contains("with")?"with":"light")}));const savedTheme=localStorage.getItem("theme");"with"===savedTheme&&htmlElement.classList.add("with");